import React from 'react';
const Navbar = () => {
    return (
        <nav className="navbar navbar-expand-lg bg-body-tertiary">
            <div className="container-fluid">
                <button
                    className="navbar-toggler collapsed"
                    type="button"
                    data-bs-toggle="collapse"
                    data-bs-target="#navbarSupportedContent"
                    aria-controls="navbarSupportedContent"
                    aria-expanded="false"
                    aria-label="Toggle navigation"
                >
                    <span className="navbar-toggler-icon"></span>
                </button>
                <div className="navbar-collapse collapse" id="navbarSupportedContent">
                    <ul className="navbar-nav me-auto mb-2 mb-lg-0">
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link tabs-controls__link--active" data-id="1">
                                Home
                            </a>
                        </li>
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link" data-id="2">
                                About
                            </a>
                        </li>
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link" data-id="3">
                                Skills
                            </a>
                        </li>
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link" data-id="4">
                                Experience
                            </a>
                        </li>
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link" data-id="5">
                               Projects
                            </a>
                        </li>
                        <li className="nav-item tabs-controls__item">
                            <a className="tabs-controls__link" data-id="6">
                                Contact Me
                            </a>
                        </li>
                    </ul>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
