
import '../styles/experience.css';
import React from 'react';
import { Box, Container, Typography, List, ListItem, Link } from "@mui/material";
import ExperienceData from "../Assets/Data/workExperience.json"
function Experience() {

  let workExperience = ExperienceData.workExperience;

  return (
    <>
      <Container
        maxWidth="lg"
        sx={{
          padding: { xs: "16px", sm: "24px", md: "32px" },
          backgroundColor: "#f5f5f5",
          borderRadius: "8px",
          boxShadow: { xs: "none", sm: "0 4px 10px rgba(0,0,0,0.1)" },
          marginY: { xs: "16px", sm: "24px" },
        }}
      >

        <Box sx={{ textAlign: { xs: "center", sm: "left" } }}>
          <Typography variant="h4" gutterBottom sx={{ maxInlineSize: "100%", fontFamily: '"Caveat", cursive'}}>
            {workExperience[0].title}
          </Typography>
        </Box>
        <Typography variant="h5" gutterBottom sx={{ maxInlineSize: "100%", width: "100%" ,fontFamily: '"Caveat", cursive'}}>
          {workExperience[0].company.role} | {workExperience[0].company.name}
        </Typography>
        <Typography variant="body1" gutterBottom sx={{ width: "100%",fontFamily: '"Caveat", cursive' }}>
          {workExperience[0].location} | {workExperience[0].period}
        </Typography>


        <Typography align='' variant="h6" gutterBottom sx={{ maxInlineSize: "100%", width: "100%",fontFamily: '"Caveat", cursive' }}>
          Project: {workExperience[0].project.name}
        </Typography>
        <Typography variant="body1" paragraph sx={{ width: "100%" ,fontFamily: '"Caveat", cursive'}}>
          {workExperience[0].project.description}
        </Typography>


        <Typography variant="h6" gutterBottom>
          Technologies:
        </Typography>
        <List className="Tech-style">
          {workExperience[0].project.technologies.map((tech, index) => (
            <ListItem key={index} style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <img src={tech.img} alt={tech.name} width="24" height="24" style={{ borderRadius: "4px" }} />
              {tech.name}
            </ListItem>
          ))}
        </List>
        <Typography variant="h6" gutterBottom>
          Tools:
        </Typography>
        <List className="Tech-style">
          {workExperience[0].project.tools.map((tech, index) => (
            <ListItem key={index} style={{ display: "flex", alignItems: "center", gap: "10px" }}>
              <img src={tech.img} alt={tech.title} width="24" height="24" style={{ borderRadius: "4px" }} />
              {tech.title}
            </ListItem>
          ))}
        </List>
        <Typography variant="h6" gutterBottom>
          Key Achievements:
        </Typography>
        <List className='Tech-style'>
          {workExperience[0].keyAchievements.map((achievement, index) => (
            <ListItem key={index}>➼ {achievement}</ListItem>
          ))}
        </List>

        <Box sx={{ textAlign: "center", marginTop: "16px" }}>
          <Link href="https://acumentec.com/acumentec_usa/index.html" underline="hover">
            {workExperience[0].company.name}
          </Link>
        </Box>
      </Container>

    </>
  );
}

export default Experience;